"154 :     private Archive readHeaders(byte[] password) throws IOException {
155 :         final byte[] signature = new byte[6];
156 :         file.readFully(signature);
157 :         if (!Arrays.equals(signature, sevenZSignature)) {
158 :             throw new IOException("Bad 7z signature");
159 :         }
160 :         // 7zFormat.txt has it wrong - it's first major then minor
161 :         final byte archiveVersionMajor = file.readByte();
162 :         final byte archiveVersionMinor = file.readByte();
163 :         if (archiveVersionMajor != 0) {
164 :             throw new IOException(String.format("Unsupported 7z version (%d,%d)",
165 :                     Byte.valueOf(archiveVersionMajor), Byte.valueOf(archiveVersionMinor)));
166 :         }
167 : 
168 :         final long startHeaderCrc = 0xffffFFFFL & Integer.reverseBytes(file.readInt());
169 :         final StartHeader startHeader = readStartHeader(startHeaderCrc);
170 :         
171 :         final int nextHeaderSizeInt = (int) startHeader.nextHeaderSize;
172 :         if (nextHeaderSizeInt != startHeader.nextHeaderSize) {
173 :             throw new IOException("cannot handle nextHeaderSize " + startHeader.nextHeaderSize);
174 :         }
175 :         file.seek(SIGNATURE_HEADER_SIZE + startHeader.nextHeaderOffset);
176 :         final byte[] nextHeader = new byte[nextHeaderSizeInt];
177 :         file.readFully(nextHeader);
178 :         final CRC32 crc = new CRC32();
179 :         crc.update(nextHeader);
180 :         if (startHeader.nextHeaderCrc != crc.getValue()) {
181 :             throw new IOException("NextHeader CRC mismatch");
182 :         }
183 :         
184 :         final ByteArrayInputStream byteStream = new ByteArrayInputStream(nextHeader);
185 :         DataInputStream nextHeaderInputStream = new DataInputStream(
186 :                 byteStream);
187 :         Archive archive = new Archive();
188 :         int nid = nextHeaderInputStream.readUnsignedByte();
189 :         if (nid == NID.kEncodedHeader) {
190 :             nextHeaderInputStream =
191 :                 readEncodedHeader(nextHeaderInputStream, archive, password);
192 :             // Archive gets rebuilt with the new header
193 :             archive = new Archive();
194 :             nid = nextHeaderInputStream.readUnsignedByte();
195 :         }
196 :         if (nid == NID.kHeader) {
197 :             readHeader(nextHeaderInputStream, archive);
198 :             nextHeaderInputStream.close();
199 :         } else {
200 :             throw new IOException("Broken or unsupported archive: no Header");
201 :         }
202 :         return archive;
203 :     }"

